{
  "subtype": "predictive_feature_engineering",
  "focus_variable": "state_declined",
  "per_column": [
    {
      "name": "has_processed_date",
      "role": "leakage",
      "is_predictor": false,
      "rationale": "Whether a processed_date exists is a post-outcome artifact of the expense being processed/adjudicated. A declined expense's processing status is tied to reaching a terminal state, so this indicator is knowable only after (or as part of) the outcome and leaks the resolution rather than predicting it ex ante."
    },
    {
      "name": "is_customer_support_travel",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Derived from department/context, this flags a specific requesting group. Department is a legitimate ex-ante attribute known at submission and can plausibly carry signal about approval/decline rates, lying outside the focus variable."
    },
    {
      "name": "is_sales_travel",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Same as above: a pre-outcome categorical indicator of the submitting group/travel type. Known before adjudication and plausibly correlated with decline likelihood without restating or leaking the outcome."
    }
  ],
  "n_predictors": 2,
  "predictive_utility": 0.35,
  "rationale": "Two of the three columns (department/travel-type indicators) are legitimate ex-ante predictors, though they are one-hot restatements of the already-present 'department'/'category' fields and thus add limited leverage beyond the original table. The has_processed_date flag leaks the outcome since processing status is a post-adjudication artifact. As a set, modest genuine predictive signal, discounted for redundancy with existing columns and one leaking feature."
}

